create or replace function public.reject_reserved_transfer_provenance() returns trigger language plpgsql security definer set search_path=public as $$ begin if session_user <> 'postgres' then if coalesce(new.provenance,'{}'::jsonb) ? 'inheritance_origin' or coalesce(new.provenance,'{}'::jsonb) ? 'clone_origin' then raise exception 'PROVENANCE_REJECTED: reserved transfer provenance is system-managed'; end if; end if; return new; end; $$;